record.field:
for lead in records:
    if not lead.email_normalized and not lead.phone_sanitized:
        continue  # nothing to match on

    # match on email OR phone
    criteria = []
    if lead.email_normalized:
        criteria.append(('email_normalized', '=', lead.email_normalized))
    if lead.phone_sanitized:
        criteria.append(('phone_sanitized', '=', lead.phone_sanitized))
    or_part = criteria if len(criteria) == 1 else ['|'] + criteria

    # the EARLIEST matching lead is the original
    original = env['crm.lead'].search(
        [('type', '=', 'lead')] + or_part,
        order='create_date asc, id asc', limit=1,
    )

    # if the earliest match is this lead itself -> it's an original, stop
    if not original or original.id == lead.id:
        continue

    # never link to a duplicate: if the match is one, jump to its original
    if original.x_studio_duplicate and original.x_studio_original_lead:
        original = original.x_studio_original_lead

    lead.write({
        'x_studio_duplicate': True,
        'x_studio_original_lead': original.id,
    })
